package de.rub.nds.modifiablevariable;
import de.rub.nds.modifiablevariable.longint.ModifiableLong;
import de.rub.nds.modifiablevariable.integer.ModifiableInteger;
import de.rub.nds.modifiablevariable.bytearray.ModifiableByteArray;
public final class ModifiableVariableFactory {
 public static ModifiableLong safelySetValue(ModifiableLong old,long x){return new ModifiableLong(x);}
 public static ModifiableInteger safelySetValue(ModifiableInteger old,int x){return new ModifiableInteger(x);}
 public static ModifiableByteArray safelySetValue(ModifiableByteArray old,byte[] x){return new ModifiableByteArray(x);}
}
