package de.rub.nds.modifiablevariable.util;
import java.math.BigInteger;
/** Small offline byte conversion adapter. */
public final class DataConverter {
 public static byte[] longToBytes(long x,int n){byte[] b=new byte[n];for(int i=n-1;i>=0;i--){b[i]=(byte)x;x>>>=8;}return b;}
 public static byte[] intToBytes(int x,int n){return longToBytes(x,n);}
 public static int bytesToInt(byte[] b){int x=0;for(byte v:b)x=(x<<8)|(v&255);return x;}
 public static byte[] bigIntegerToByteArray(BigInteger x,int n,boolean unused){byte[] b=x.toByteArray(),a=new byte[n];int k=Math.min(n,b.length);System.arraycopy(b,b.length-k,a,n-k,k);return a;}
}
